import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Scanner from './Scanner';
import Results from './Results';
import { LogOut, User, Shield, Activity } from 'lucide-react';

const Dashboard = ({ user, sessionId, accessToken, onLogout }) => {
  const [repositories, setRepositories] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState(null);
  const [scanResults, setScanResults] = useState(null);
  const [scanning, setScanning] = useState(false);
  const [activeTab, setActiveTab] = useState('scan');

  useEffect(() => {
    fetchRepositories();
  }, []);

  const fetchRepositories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/user/repos', {
        headers: {
          'Authorization': `Bearer ${accessToken}`,
          'X-Session-ID': sessionId
        }
      });
      setRepositories(response.data.repositories);
    } catch (error) {
      console.error('Failed to fetch repositories:', error);
    }
  };

  const handleScan = async (repoUrl) => {
    setScanning(true);
    setScanResults(null);
    
    try {
      const response = await axios.post('http://localhost:5000/api/scan', 
        { repo_url: repoUrl },
        {
          headers: {
            'Authorization': `Bearer ${accessToken}`,
            'X-Session-ID': sessionId,
            'Content-Type': 'application/json'
          }
        }
      );
      
      setScanResults(response.data);
      setActiveTab('results');
    } catch (error) {
      console.error('Scan failed:', error);
      alert('Failed to scan repository. Please try again.');
    } finally {
      setScanning(false);
    }
  };

  return (
    <div className="dashboard">
      <nav className="navbar">
        <div className="nav-brand">
          <Shield size={24} />
          <span>VulnScanner</span>
        </div>
        
        <div className="nav-tabs">
          <button 
            className={`nav-tab ${activeTab === 'scan' ? 'active' : ''}`}
            onClick={() => setActiveTab('scan')}
          >
            <Activity size={18} />
            Scan Repository
          </button>
          {scanResults && (
            <button 
              className={`nav-tab ${activeTab === 'results' ? 'active' : ''}`}
              onClick={() => setActiveTab('results')}
            >
              Results ({scanResults.total_count})
            </button>
          )}
        </div>
        
        <div className="user-info">
          <img src={user.avatar_url} alt={user.login} className="avatar" />
          <span>{user.login}</span>
          <button onClick={onLogout} className="logout-btn">
            <LogOut size={18} />
          </button>
        </div>
      </nav>
      
      <div className="dashboard-content">
        {activeTab === 'scan' && (
          <Scanner 
            repositories={repositories}
            onScan={handleScan}
            scanning={scanning}
          />
        )}
        
        {activeTab === 'results' && scanResults && (
          <Results results={scanResults} />
        )}
      </div>
    </div>
  );
};

export default Dashboard;
